 folder=o/source;meta=json.loads((folder/"complete.json").read_text());parent=ROOT/"phase28"/f"{source}_joint_0";a=torch.load(folder/"model.pt",map_location="cpu",weights_only=False)["state"];b=torch.load(parent/"model.pt",map_location="cpu",weights_only=False)["state"];allowed={"mask_token","aux_head.weight","aux_head.bias"};assert a.keys()==b.keys();assert all(torch.equal(a[k],b[k]) for k in a if k not in allowed);assert set(meta["trainable_names"])==allowed;assert hashlib.sha256((parent/"model.pt").read_bytes()).hexdigest()==meta["parent_classifier_sha256"];assert abs(meta["best_aux_ce"]-min([np.mean([v["masked_ce"] for v in meta["initial_auxiliary"].values()])]+[h["auxiliary_ce"] for h in meta["history"]]))<1e-10
