 for metric in ["future_ce_gain","balanced_ce_gain","accuracy_gain_pp","sample_macro_f1_gain_pp"]:
  pivot=g.pivot(index="subject",columns="variant",values=metric);d=(pivot.fitted-pivot.unfitted).to_numpy();rng=np.random.default_rng(20261006);ci=np.quantile(rng.choice(d,(20000,4)).mean(1),[.025,.975]);paired.append(dict(source=source,lr=lr,metric=metric,fitted_minus_unfitted=float(d.mean()),ci_low=float(ci[0]),ci_high=float(ci[1]),positive_people=int((d>0).sum())))
